            if (sameLookupValue(target.path, current.value, target.value)) continue;
            const earlier = answered.find(item => item.path === target.path && sameDraftValue(item.lookup, target.value));
            conflicts.push({ path: target.path, lookup: structuredClone(target.value), slotId: target.slotId, answer: earlier?.answer ?? null });
            continue;
